'use strict';
const stageUrl=(id,n)=>`#${id}${n?'-'+n:''}`;
function stageNav(id,n,last,label='Continuar',enabled=true){return `<div class="stage-nav">${n?`<a class="btn ghost" href="${stageUrl(id,n-1)}">← Volver</a>`:`<button class="text-button" data-open-modules aria-haspopup="dialog" aria-controls="modules-dialog">← Módulos</button>`}${n<last?(enabled?`<a class="btn" href="${stageUrl(id,n+1)}">${label} →</a>`:`<button class="btn" disabled>${label} →</button>`):'<button class="btn" data-open-modules aria-haspopup="dialog" aria-controls="modules-dialog">Elegir otro módulo →</button>'}</div>`;}
function stageFrame(id,title,n,total,body){return head(`APRENDE A TU RITMO / ${title}`,title,'Una idea. Una decisión. Un paso más.')+moduleProgress(n,total)+`<section class="card focus-card">${body}</section>`;}
function ideaCard(id,title,n,total,icon,heading,copy,example){return stageFrame(id,title,n,total,`<span class="focus-icon" aria-hidden="true">${icon}</span><span class="eyebrow">LA IDEA CLAVE</span><h2>${heading}</h2><p class="focus-copy">${copy}</p>${example?`<div class="mini-example">${example}</div>`:''}${stageNav(id,n,total-1,'Lo tengo')}`);}

function phishingFlow(){
 const n=Math.max(0,Math.min(15,activeStage)),title='Detecta el phishing';
 const ideas=[['✉','El nombre no demuestra quién escribe.','El phishing suplanta a alguien para que entregues datos o hagas clic. Comprueba el remitente por un canal que ya conozcas.','Un logo se puede copiar. Una dirección oficial se verifica.'],['⌘','Tus claves y códigos son privados.','Si un mensaje solicita tu contraseña o un código de verificación, detente. No respondas ni lo introduzcas en el enlace recibido.','Accede al servicio desde su aplicación o una dirección conocida.'],['◷','La prisa también es una señal.','Los premios inesperados y las amenazas buscan que decidas sin pensar. Respira, revisa y verifica antes de actuar.','Ahora verás un mensaje ficticio a la vez.']];
 if(n<3)return ideaCard('phishing',title,n,16,...ideas[n]);
 if(n===15){const count=Object.keys(state.phish).length,hits=Object.entries(state.phish).filter(([i,a])=>a===scenarios[i].phish).length;return stageFrame('phishing',title,n,16,`<span class="focus-icon">✓</span><span class="eyebrow">LO QUE TE LLEVAS</span><h2>${count===6?'Una pausa puede protegerte.':'Aún hay mensajes por explorar.'}</h2><p class="focus-copy">Verifica quién escribe, qué solicita y por qué te presiona.</p><div class="mini-example">${hits} aciertos · ${count} de 6 mensajes revisados</div>${stageNav('phishing',n,15)}`);}
 const index=Math.floor((n-3)/2),s=scenarios[index],answer=state.phish[index],answered=typeof answer==='boolean';phishIndex=index;
 if(n%2===0){if(!answered)return stageFrame('phishing',title,n,16,`<h2>Primero observa el mensaje.</h2><p>Responde antes de revisar la explicación.</p><a class="btn" href="${stageUrl('phishing',n-1)}">Volver al mensaje →</a>`);return stageFrame('phishing',title,n,16,`<span class="focus-icon ${answer===s.phish?'':'soft'}">${answer===s.phish?'✓':'↺'}</span><span class="eyebrow">LA EXPLICACIÓN</span><h2>${s.phish?'Este mensaje intenta engañarte.':'No muestra señales de phishing.'}</h2><p class="focus-copy">${s.why}</p><div class="mini-example"><b>Qué hacer</b><p>${s.action}</p></div><details class="focus-details"><summary>Ver las señales del mensaje</summary><ul>${s.clues.map(c=>`<li>${c}</li>`).join('')}</ul></details>${stageNav('phishing',n,15,n===14?'Ver mi resumen':'Otro mensaje')}`);}
 return stageFrame('phishing',title,n,16,`<span class="eyebrow">MENSAJE FICTICIO · ${index+1} DE 6</span><h2>${s.subject}</h2><div class="mail-top"><div class="mail-avatar">${s.from[0]}</div><div><b>${s.from}</b><small class="sender-address">${s.address}</small></div></div><p class="mail-body">${s.body}</p>${s.url?`<div class="fake-link">${s.url}</div>`:''}<p class="practice-caption">Simulación: los enlaces no se abren.</p><div class="decision-buttons"><button class="btn" data-phish="true" ${answered?'disabled':''}>Es phishing</button><button class="btn ghost" data-phish="false" ${answered?'disabled':''}>Sin señales de phishing</button></div>${answered?stageNav('phishing',n,15,'Ver explicación'):stageNav('phishing',n,15,'Elige una respuesta',false)}`);
}
function passwordFlow(){
 const n=Math.max(0,Math.min(4,activeStage)),title='Protege tus claves';
 const ideas=[['⌘','Empieza por la longitud.','Una frase larga e impredecible es más difícil de adivinar. Evita nombres, fechas y frases populares.','Imagina varias palabras sin relación entre sí.'],['◈','Una clave distinta para cada cuenta.','Reutilizar una contraseña permite que una filtración afecte varios servicios. Un gestor puede ayudarte a crear y recordar claves únicas.','No necesitas memorizar todas las contraseñas.'],['◎','Añade otra comprobación.','La autenticación multifactor solicita una prueba adicional para entrar. Nunca compartas los códigos que recibas.','En el siguiente paso solo usarás una contraseña ficticia.']];
 if(n<3)return ideaCard('claves',title,n,5,...ideas[n]);
 if(n===4)return stageFrame('claves',title,n,5,`<span class="focus-icon">${state.password?'✓':'⌘'}</span><span class="eyebrow">LO QUE TE LLEVAS</span><h2>${state.password?'Larga, única e impredecible.':'Te queda probar una frase.'}</h2><p class="focus-copy">Combina una contraseña distinta por cuenta con autenticación multifactor.</p><div class="mini-example">${state.password?'Completaste la práctica con un ejemplo.':'Vuelve al laboratorio y analiza un ejemplo para completar.'}</div>${stageNav('claves',n,4)}`);
 return stageFrame('claves',title,n,5,`<span class="eyebrow">PRUÉBALO TÚ</span><h2>Construye una frase de ejemplo.</h2><p class="practice-caption">Nunca introduzcas una contraseña real. El ejemplo no se guarda ni se envía.</p><label class="field" for="password">Contraseña ficticia</label><input id="password" type="password" maxlength="160" autocomplete="off" spellcheck="false" placeholder="Escribe una frase inventada"><label class="checklabel"><input id="show-password" type="checkbox">Mostrar ejemplo</label><div id="strength" aria-live="polite"><div class="meter"><div style="width:0%"></div></div><p class="muted">Escribe para ver una recomendación.</p></div><button class="text-button" id="sample-password">Necesito un ejemplo</button><div class="stage-nav"><a class="btn ghost" href="#claves-2">← Volver</a><button class="btn" id="complete-password" disabled>Ver resumen →</button></div>`);
}
function cipherFlow(){
 const n=Math.max(0,Math.min(8,activeStage)),title='Descubre el cifrado';
 if(n===0)return ideaCard('cifrado',title,n,9,'⌁','Un mensaje cambia con una clave.','Cifrar transforma un mensaje legible. La clave adecuada permite recuperarlo.','Mensaje original → clave → mensaje cifrado');
 if(n===1)return ideaCard('cifrado',title,n,9,'ABC','César desplaza las letras.','Con un desplazamiento de 3 posiciones, A se convierte en D. Es un ejemplo para aprender; sus pocas claves no protegen datos reales.','A → D · B → E · C → F');
 if(n===2){cipherMode='cesar';return stageFrame('cifrado',title,n,9,`<span class="eyebrow">PRUÉBALO TÚ · CÉSAR</span><h2>Transforma tu mensaje.</h2><label class="field" for="plain">Mensaje ficticio</label><textarea id="plain" maxlength="2000">PROTEGE TUS DATOS</textarea><label class="field" for="shift">Desplazamiento: <span id="shift-value">3</span></label><input id="shift" type="range" min="1" max="25" value="3"><div id="letter-map" class="letter-map"></div><p class="practice-caption">Cambiamos A–Z. Espacios, tildes y ñ se conservan.</p><div class="stage-nav"><a class="btn ghost" href="#cifrado-1">← Volver</a><button class="btn" id="caesar-encrypt">Cifrar y continuar →</button></div>`);}
 if(n===3){if(!caesarRecord)return stageFrame('cifrado',title,n,9,`<h2>Primero cifra un mensaje.</h2><p>El ejemplo solo existe durante esta práctica.</p><a class="btn" href="#cifrado-2">Crear mi ejemplo →</a>`);return stageFrame('cifrado',title,n,9,`<span class="eyebrow">RECUPERA EL MENSAJE</span><h2>La misma clave deshace el cambio.</h2><div class="code-output">${esc(caesarRecord.value)}</div><p class="practice-caption">Desplazamiento utilizado: ${caesarRecord.shift}.</p><button class="btn ghost" id="caesar-decrypt">Descifrar</button><p class="mini-example" id="cipher-recovered" ${caesarRecord.recovered?'':'hidden'}>${caesarRecord.recovered?'Mensaje recuperado: '+esc(caesar(caesarRecord.value,-caesarRecord.shift)):''}</p><div id="cipher-next">${stageNav('cifrado',n,8,'Conocer AES',caesarRecord.recovered)}</div>`);}
 if(n===4)return ideaCard('cifrado',title,n,9,'◈','AES protege con una clave secreta.','Ahora probarás AES-GCM. El navegador creará una clave aleatoria y la usará para cifrar y recuperar tu mensaje.','La clave y los mensajes desaparecen al salir del módulo.');
 if(n===5){cipherMode='aes';return stageFrame('cifrado',title,n,9,`<span class="eyebrow">PRUÉBALO TÚ · AES-GCM</span><h2>Crea un secreto nuevo.</h2><p class="practice-caption">La clave se genera en este dispositivo. Usa solo información ficticia.</p><label class="field" for="aes-plain">Mensaje de práctica</label><textarea id="aes-plain" maxlength="2000">Mi información es privada.</textarea>${!globalThis.crypto?.subtle?'<div class="notice">AES necesita HTTPS o localhost en un navegador compatible. Puedes completar la práctica con César.</div>':''}<div class="stage-nav"><a class="btn ghost" href="#cifrado-4">← Volver</a>${globalThis.crypto?.subtle?'<button class="btn" id="aes-encrypt">Crear clave y cifrar →</button>':'<a class="btn" href="#cifrado-8">Ver resumen →</a>'}</div>`);}
 if(n===6||n===7){if(!aesBytes)return stageFrame('cifrado',title,n,9,`<h2>Crea primero tu secreto.</h2><p>La clave de esta práctica no se conserva al salir.</p><a class="btn" href="#cifrado-5">Cifrar un mensaje →</a>`);
  if(n===6)return stageFrame('cifrado',title,n,9,`<span class="eyebrow">RECUPERA EL MENSAJE</span><h2>El resultado ya no se puede leer.</h2><div class="code-output">${btoa(String.fromCharCode(...new Uint8Array(aesBytes)))}</div><p class="practice-caption">Base64 permite mostrar los bytes como texto. La protección la aporta AES-GCM.</p><button class="btn ghost" id="aes-decrypt">Descifrar con mi clave</button><p id="aes-recovered" class="mini-example" ${aesRecovered?'':'hidden'}>${aesRecovered?'Mensaje recuperado: '+esc(aesRecovered):''}</p><div id="cipher-next">${stageNav('cifrado',n,8,'Probar otra clave',Boolean(aesRecovered))}</div>`);
  return stageFrame('cifrado',title,n,9,`<span class="focus-icon">⌘</span><span class="eyebrow">UNA ÚLTIMA COMPROBACIÓN</span><h2>¿Y si la clave es distinta?</h2><p class="focus-copy">Intenta abrir el mismo mensaje con otra clave. Observa qué ocurre.</p><button class="btn ghost" id="aes-wrong">Probar otra clave</button><p id="aes-feedback" role="status"></p>${stageNav('cifrado',n,8,'Ver resumen')}`);
 }
 return stageFrame('cifrado',title,n,9,`<span class="focus-icon">${state.cipher?'✓':'⌁'}</span><span class="eyebrow">LO QUE TE LLEVAS</span><h2>La clave hace la diferencia.</h2><p class="focus-copy">César ayuda a entender el mecanismo. AES-GCM usa una clave secreta y puede detectar cambios en el mensaje cifrado.</p><div class="mini-example">${state.cipher?'Cifraste y recuperaste un mensaje.':'Recupera un mensaje en César o AES para completar la práctica.'}</div>${stageNav('cifrado',n,8)}`);
}
function extraFlow(id){
 const m=learningModules.find(x=>x.id===id),n=Math.max(0,Math.min(9,activeStage));
 if(n<3)return ideaCard(id,m.title,n,10,m.icon,m.terms[n][0],m.terms[n][1],null);
 if(n===9){const score=lessonStats(id);return stageFrame(id,m.title,n,10,`<span class="focus-icon">${lessonDone(id)?'✓':m.icon}</span><span class="eyebrow">LO QUE TE LLEVAS</span><h2>${lessonDone(id)?'Cada decisión te enseña.':'Continúa con las situaciones.'}</h2><p class="focus-copy">${score.correct} aciertos de ${score.answered} respuestas. Puedes volver a las ideas cuando quieras.</p><details class="focus-details"><summary>Quiero profundizar</summary><a class="inline-link source-link" href="${m.source}" target="_blank" rel="noopener noreferrer">${m.sourceName} ↗</a></details>${stageNav(id,n,9)}`);}
 const i=Math.floor((n-3)/2),c=m.cases[i],a=lessonRecord(id)[i],answered=Number.isInteger(a);
 if(n%2===0)return stageFrame(id,m.title,n,10,answered?`<span class="focus-icon ${a===c.correct?'':'soft'}">${a===c.correct?'✓':'↺'}</span><span class="eyebrow">LA EXPLICACIÓN</span><h2>${a===c.correct?'Una buena decisión.':'Una oportunidad para aprender.'}</h2><p class="focus-copy">${c.why}</p><div class="mini-example"><b>La mejor opción</b><p>${c.options[c.correct]}</p></div>${stageNav(id,n,9,n===8?'Ver resumen':'Otro reto')}`:`<h2>Primero toma una decisión.</h2><a class="btn" href="${stageUrl(id,n-1)}">Volver al reto →</a>`);
 return stageFrame(id,m.title,n,10,`<span class="eyebrow">SITUACIÓN FICTICIA · ${i+1} DE 3</span><h2>${c.title}</h2><p class="focus-copy">${c.text}</p><fieldset class="lesson-options"><legend>¿Qué harías?</legend>${c.options.map((o,j)=>`<button class="lesson-choice ${a===j?'selected':''}" data-lesson-answer="${j}" ${answered?'disabled':''}><span class="choice-letter">${String.fromCharCode(65+j)}</span><span>${o}</span></button>`).join('')}</fieldset>${stageNav(id,n,9,answered?'Ver explicación':'Elige una respuesta',answered)}`);
}
function bindCoreFlow(route){
 $$('[data-phish]').forEach(b=>b.onclick=()=>{state.phish[phishIndex]=b.dataset.phish==='true';save();location.hash=stageUrl('phishing',activeStage+1);});
 $$('[data-lesson-answer]').forEach(b=>b.onclick=()=>{const i=Math.floor((activeStage-3)/2);state.lessons[route]??={};state.lessons[route][i]=Number(b.dataset.lessonAnswer);save();location.hash=stageUrl(route,activeStage+1);});
 on('#password','input',updateStrength);on('#show-password','change',e=>$('#password').type=e.target.checked?'text':'password');on('#sample-password','click',()=>{$('#password').value='Luna-Tren-Musgo-Linterna';$('#password').type='text';$('#show-password').checked=true;updateStrength();toast('Ejemplo público: no lo uses como contraseña real.');});on('#complete-password','click',()=>{state.password=true;save();location.hash='claves-4';});
 if($('#shift')){const map=()=>{const n=Number($('#shift').value);$('#shift-value').textContent=n;$('#letter-map').innerHTML='ABC'.split('').map(c=>`<span>${c} → ${caesar(c,n)}</span>`).join('');};map();on('#shift','input',map);}
 on('#caesar-encrypt','click',()=>{const value=$('#plain').value;if(!value.trim())return toast('Escribe un mensaje ficticio.');const shift=Number($('#shift').value);caesarRecord={value:caesar(value,shift),shift,recovered:false};location.hash='cifrado-3';});
 on('#caesar-decrypt','click',()=>{if(!caesarRecord)return;caesarRecord.recovered=true;$('#cipher-recovered').textContent='Mensaje recuperado: '+caesar(caesarRecord.value,-caesarRecord.shift);$('#cipher-recovered').hidden=false;$('#cipher-next').innerHTML=stageNav('cifrado',3,8,'Conocer AES');state.cipher=true;save();});
 on('#aes-encrypt','click',async()=>{const value=$('#aes-plain').value;if(!value.trim())return toast('Escribe un mensaje ficticio.');const button=$('#aes-encrypt'),run=cipherRun;button.disabled=true;try{const key=await crypto.subtle.generateKey({name:'AES-GCM',length:256},false,['encrypt','decrypt']),iv=crypto.getRandomValues(new Uint8Array(12)),bytes=await crypto.subtle.encrypt({name:'AES-GCM',iv},key,new TextEncoder().encode(value));if(run!==cipherRun||!button.isConnected)return;aesKey=key;aesIv=iv;aesBytes=bytes;aesRecovered='';location.hash='cifrado-6';}catch{toast('No se pudo cifrar. Usa un navegador con HTTPS o localhost.');}finally{if(button.isConnected)button.disabled=false;}});
 on('#aes-decrypt','click',async()=>{const run=cipherRun;try{const out=await crypto.subtle.decrypt({name:'AES-GCM',iv:aesIv},aesKey,aesBytes);if(run!==cipherRun||!$('#aes-recovered'))return;aesRecovered=new TextDecoder().decode(out);$('#aes-recovered').textContent='Mensaje recuperado: '+aesRecovered;$('#aes-recovered').hidden=false;$('#cipher-next').innerHTML=stageNav('cifrado',6,8,'Probar otra clave');state.cipher=true;save();}catch{toast('Vuelve a crear el mensaje cifrado.');}});
 on('#aes-wrong','click',async()=>{const run=cipherRun,iv=aesIv,data=aesBytes,button=$('#aes-wrong');button.disabled=true;try{const key=await crypto.subtle.generateKey({name:'AES-GCM',length:256},false,['decrypt']);await crypto.subtle.decrypt({name:'AES-GCM',iv},key,data);if(run===cipherRun&&$('#aes-feedback'))$('#aes-feedback').textContent='La comprobación produjo un resultado inesperado.';}catch{if(run===cipherRun&&$('#aes-feedback'))$('#aes-feedback').textContent='✓ Acceso rechazado. Una clave diferente no abre el mensaje.';}finally{if(button.isConnected)button.disabled=false;}});
}
